mapper.select:
SELECT ws.id AS session_id, ws.routine_id, ws.started_at, ws.ended_at, ws.memo
FROM workout_sessions ws JOIN members m ON m.id=ws.member_id
WHERE m.user_id=#{userId} AND ws.id=#{sessionId}

mapper.delete:
DELETE ws FROM workout_sessions ws
JOIN members m ON m.id = ws.member_id
WHERE ws.id = #{sessionId} AND m.user_id = #{userId}

DELETE wset FROM workout_sets wset JOIN workout_sessions ws ON
        ws.id=wset.session_id JOIN members m ON m.id=ws.member_id WHERE m.user_id=#{userId} AND
        DATE(ws.started_at)=#{workoutDate}
